mapper.select:
select l.user_id userId, p.lat lat, p.lng lng, p.uptime `time`, p.locate_type locateType, d.nickname `nickname`, d.avatar avatar, d.avatar_status avatarStatus, d.avatar_check_status avatarCheckStatus, d.role role, d.group `group`, d.con con, d.check_status checkStatus, d.weight, d.height, d.birthday, count(1) `match` from corgi_activity_like l left join corgi_user_detail d on d.user_id = l.user_id left join corgi_user_position p on p.user_id = l.user_id where l.type = 'real' and d.avatar_check_status = 'verified' and l.like_user_id != l.user_id and (d.avatar_status not like 'fake%' or d.avatar_status is null) and l.ctime >= #{date}
and p.city = #{detail.city}
group by l.user_id order by `match` desc limit #{limit}

select count(1) `match`, user_id userId
from (
             (select user_id from corgi_activity_comment where ctime >= #{date})
             union all
             (select user_id from corgi_activity_like where ctime >= #{date} and type = 'real')
     ) a
group by user_id
order by `match` desc limit #{limit}

select user_id userId
from corgi_billboard
where `date` >= #{date}

mapper.update:
update corgi.corgi_billboard
set user_id = #{toId}
where `date` = #{date}
  and user_id = #{fromId}

update corgi.corgi_activity_billboard
set `order` = #{order}
where `date` = #{date}
  and activity_id = #{activityId}

mapper.insert:
update corgi_activity_billboard
set status = '1'
where activity_id = #{activity.activityId}
  and `date` = #{activity.date}
  and `order` = #{activity.order}

mapper.update:
update corgi_activity_billboard
set `status` = '0'
where activity_id = #{activity.activityId}
  and `date` = #{activity.date}

mapper.select:
select b.date
from corgi_activity_billboard b
         left join corgi_activity_creator c on c.activity_id = b.activity_id
where b.status = '1'
  and c.creator_id = #{userId}
  and b.date < #{date}
order by b.id desc limit 1;

select b.activity_id activityId, c.creator_id userId, (select count(1) from corgi_activity_billboard b1 left join corgi_activity_creator c1 on c1.activity_id = b1.activity_id where (c1.creator_id = c.creator_id or b1.user_id = c.creator_id) and b1.status = 1) count, b.date, b.order from corgi_activity_billboard b left join corgi_activity_creator c on c.activity_id = b.activity_id where status = 1 and `date` >= #{activity.date}
and `date` <= #{activity.ctime}
order by b.`date` desc,b.`order`

select count(1)
from corgi_billboard
where user_id = #{userId}

select count(1) from corgi_paid_billboard
where 1 = 1

    and `date` = #{paid.date}


    and `status` = #{paid.status}


    and activity_id = #{paid.activityId}

select p.id, p.activity_id activityId, p.date, p.status,o.user_id payId,p.user_id userId
from corgi_paid_billboard p
left join corgi_order o on o.trade_no = p.trade_no
where 1=1

    and p.`date` = #{paid.date}


    and p.`status` = #{paid.status}

order by p.id desc
limit #{start}, #{size}
